import { GoogleGenAI } from "@google/genai";
import { NECINA_SYSTEM_PROMPT } from "../constants";

// Correct initialization: Always use const ai = new GoogleGenAI({apiKey: process.env.API_KEY});
// Do not use default empty strings or fallbacks.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export class GeminiService {
  async getChatResponse(message: string, history: { role: string; content: string }[]) {
    try {
      // Map history roles to Gemini format: 'user' or 'model'
      const contents = history.map(h => ({
        role: h.role === 'bot' ? 'model' : 'user',
        parts: [{ text: h.content }]
      }));

      // Add the current user message
      contents.push({
        role: 'user',
        parts: [{ text: message }]
      });

      // Always use ai.models.generateContent to query GenAI with both the model name and prompt.
      // Use 'gemini-3-flash-preview' for basic text tasks and Q&A.
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: contents,
        config: {
          systemInstruction: NECINA_SYSTEM_PROMPT,
          temperature: 0.7,
        }
      });

      // The GenerateContentResponse object features a text property (not a method).
      return response.text || "I'm sorry, I couldn't process that request.";
    } catch (error) {
      console.error("Gemini Error:", error);
      return "An error occurred while connecting to the AI assistant. Please try again later.";
    }
  }
}

export const geminiService = new GeminiService();

