import React, { useState, useEffect, useMemo } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import NoticeBanner from './components/NoticeBanner';
import MissionJourney from './components/MissionJourney';
import ConversionBlock from './components/ConversionBlock';
import StayTuned from './components/StayTuned';
import ProgramAgenda from './components/ProgramAgenda';
import SponsorshipTiers from './components/SponsorshipTiers';
import InterestForms from './components/InterestForms';
import AIAssistant from './components/AIAssistant';
import type { Locale, DesignStyle } from './types';
import { STYLE_TOKENS } from './constants';

// NECINA logo blue (used as CSS variables so the whole site can reference it)
const BRAND = {
  primary: '#29B0E9',
  primaryHover: '#218DBA',
  primaryDark: '#1B7297',
  bg1: '#EAF7FD',
  bg2: '#D4EFFB',
};

const App: React.FC = () => {
  const [locale, setLocale] = useState<Locale>(() => {
    const saved = localStorage.getItem('necina_locale');
    return saved === 'zh' || saved === 'en' ? saved : 'en';
  });

  const [designStyle, setDesignStyle] = useState<DesignStyle>(() => {
    const saved = localStorage.getItem('necina_style') as DesignStyle | null;
    return saved ?? 'modern';
  });

  // Apply style tokens to the document root to update CSS variables dynamically
  useEffect(() => {
    const tokens = STYLE_TOKENS?.[designStyle];
    if (tokens) {
      Object.entries(tokens).forEach(([property, value]) => {
        document.documentElement.style.setProperty(property, value);
      });
    }

    // Ensure brand variables always exist (even if tokens don't include them)
    document.documentElement.style.setProperty('--brand', BRAND.primary);
    document.documentElement.style.setProperty('--brandHover', BRAND.primaryHover);
    document.documentElement.style.setProperty('--brandDark', BRAND.primaryDark);
    document.documentElement.style.setProperty('--brandBg1', BRAND.bg1);
    document.documentElement.style.setProperty('--brandBg2', BRAND.bg2);

    document.documentElement.setAttribute('data-style', designStyle);
    localStorage.setItem('necina_style', designStyle);
  }, [designStyle]);

  // Persist locale + expose to DOM for future components
  useEffect(() => {
    document.documentElement.setAttribute('data-locale', locale);
    document.documentElement.lang = locale === 'zh' ? 'zh-CN' : 'en';
    localStorage.setItem('necina_locale', locale);
  }, [locale]);

  // Minimal i18n (so you can SEE it working immediately, without editing other components yet)
  const t = useMemo(() => {
    if (locale === 'zh') {
      return {
        sponsorWallTitle: '30 年合作伙伴（示例）',
        footerTagline: '自 1996 年以来，赋能专业人士、创业者与学生。',
        explore: '导航',
        contact: '联系方式',
        links: {
          mission: '我们的使命',
          journey: '30 年历程',
          sponsorship: '赞助合作',
          membership: '会员',
        },
        email: '邮箱：contact@necina.org',
      };
    }
    return {
      sponsorWallTitle: 'Featured Partners of 30 Years',
      footerTagline: 'Empowering professionals, entrepreneurs, and students since 1996.',
      explore: 'Explore',
      contact: 'Contact',
      links: {
        mission: 'Our Mission',
        journey: '30-Year Journey',
        sponsorship: 'Sponsorship',
        membership: 'Membership',
      },
      email: 'Email: contact@necina.org',
    };
  }, [locale]);

  return (
    <div
      className="min-h-screen transition-all duration-500 ease-in-out"
      style={{
        backgroundColor: 'var(--surface)',
        color: 'var(--text)',
        backgroundImage: 'var(--hero)',
      }}
    >
      <Navbar
        locale={locale}
        setLocale={setLocale}
        designStyle={designStyle}
        setDesignStyle={setDesignStyle}
      />

      {/* key={locale}：切换语言时强制重挂载，避免“看起来没反应” */}
      <main key={locale}>
        <Hero locale={locale} />
        <NoticeBanner locale={locale} />
