import React, { useMemo } from 'react';
import { ANNIVERSARY_AGENDA } from '../constants';
import type { Locale, DesignStyle } from '../types';

type Props = {
  locale: Locale;
  designStyle: DesignStyle;
};

// 兼容：title / title_zh / title.en|zh 等
function pickText(locale: Locale, obj: any, baseKey: string): string | undefined {
  if (!obj) return undefined;

  const nested = obj[baseKey];
  if (nested && typeof nested === 'object') {
    const v = locale === 'zh' ? nested.zh : nested.en;
    if (typeof v === 'string' && v.trim()) return v;
  }

  const suffixKey = `${baseKey}_${locale === 'zh' ? 'zh' : 'en'}`;
  if (typeof obj[suffixKey] === 'string' && obj[suffixKey].trim()) return obj[suffixKey];

  if (typeof obj[baseKey] === 'string' && obj[baseKey].trim()) return obj[baseKey];

  return undefined;
}

// 英文到中文 fallback（当 constants 没有中文字段时使用）
const AGENDA_TRANSLATIONS: Record<string, string> = {
  'Registration & Networking': '签到注册与交流',
  'Opening Remarks': '开场致辞',
  'Keynote Session': '主旨演讲',
  'Legacy Panel': '传承圆桌',
  'Anniversary Gala Dinner': '周年庆晚宴',
  'NECINA President & Distinguished Guests': 'NECINA 会长及特邀嘉宾',
  'Founding Members': '创始成员',
  'Early check-in and community coffee hour.': '提前签到与社区交流时间。',
  TBD: '待定',
};

function translateIfNeeded(locale: Locale, text?: string) {
  if (!text) return text;
  if (locale !== 'zh') return text;
  return AGENDA_TRANSLATIONS[text] ?? text;
}

type ViewItem = {
  time: string;
  title: string;
  speaker?: string;
  description?: string;
};

export default function ProgramAgenda({ locale, designStyle }: Props) {
  const heading = useMemo(() => (locale === 'zh' ? '活动日程' : 'Program Agenda'), [locale]);

  const items: ViewItem[] = useMemo(() => {
    return ANNIVERSARY_AGENDA.map((item: any) => {
      const rawTitle = pickText(locale, item, 'title') ?? '';
      const rawSpeaker = pickText(locale, item, 'speaker');
      const rawDesc = pickText(locale, item, 'description');

      return {
        time: item.time,
        title: translateIfNeeded(locale, rawTitle) ?? '',
        speaker: translateIfNeeded(locale, rawSpeaker),
        description: translateIfNeeded(locale, rawDesc),
      };
    });
  }, [locale]);

  // ---------- STYLE: MINIMAL ----------
  if (designStyle === 'minimal') {
    return (
      <section className="py-24 bg-white" id="program">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex flex-col md:flex-row md:items-end justify-between mb-16 gap-4">
            <div className="max-w-xl">
              <h2 className="text-4xl font-black tracking-tight" style={{ color: 'var(--text)' }}>
                {heading}
              </h2>
              <p className="mt-3 text-lg text-slate-500">
                {locale === 'zh' ? '加入我们的庆典，见证三十年的非凡历程。' : 'Join us for a day of celebration, reflection, and community growth.'}
              </p>
            </div>
          </div>

          <div className="max-w-4xl border-t border-slate-100 divide-y divide-slate-100">
            {items.map((it, idx) => (
              <div key={idx} className="group py-8 flex flex-col md:flex-row items-start gap-8 hover:bg-slate-50/50 transition-colors px-4 -mx-4 rounded-xl">
                <div className="w-32 shrink-0">
                  <span className="text-sm font-black tracking-widest uppercase text-primary">
                    {it.time}
                  </span>
                </div>
                <div className="flex-1">
                  <h3 className="text-xl font-bold text-slate-900 group-hover:text-primary transition-colors">
                    {it.title}
                  </h3>
                  {it.speaker && (
                    <div className="mt-1 flex items-center gap-2">
                      <div className="w-1 h-1 rounded-full bg-slate-300" />
                      <span className="text-sm font-semibold text-slate-500">
                        {it.speaker}
                      </span>
                    </div>
                  )}
                  {it.description && (
                    <p className="mt-3 text-sm leading-relaxed text-slate-400 max-w-2xl">
                      {it.description}
                    </p>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>
    );
  }

  // ---------- STYLE: MODERN ----------
  if (designStyle === 'modern') {
    return (
      <section className="py-20" id="program" style={{ background: '#070B14', color: '#fff' }}>
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-12">
