import React, { useMemo } from 'react';
import { SPONSOR_TIERS } from '../constants';
import type { Locale, DesignStyle } from '../types';

type Props = {
  locale: Locale;
  designStyle: DesignStyle;
};

function pickText(locale: Locale, obj: any, baseKey: string): string | undefined {
  if (!obj) return undefined;

  const nested = obj[baseKey];
  if (nested && typeof nested === 'object') {
    const v = locale === 'zh' ? nested.zh : nested.en;
    if (typeof v === 'string' && v.trim()) return v;
  }

  const suffixKey = `${baseKey}_${locale === 'zh' ? 'zh' : 'en'}`;
  if (typeof obj[suffixKey] === 'string' && obj[suffixKey].trim()) return obj[suffixKey];

  if (typeof obj[baseKey] === 'string' && obj[baseKey].trim()) return obj[baseKey];

  return undefined;
}

function pickArray(locale: Locale, obj: any, baseKey: string): string[] | undefined {
  if (!obj) return undefined;

  const nested = obj[baseKey];
  if (nested && typeof nested === 'object' && !Array.isArray(nested)) {
    const arr = locale === 'zh' ? nested.zh : nested.en;
    if (Array.isArray(arr) && arr.length) return arr;
  }

  const suffixKey = `${baseKey}_${locale === 'zh' ? 'zh' : 'en'}`;
  if (Array.isArray(obj[suffixKey]) && obj[suffixKey].length) return obj[suffixKey];

  if (Array.isArray(obj[baseKey]) && obj[baseKey].length) return obj[baseKey];

  return undefined;
}

// 档位名 & 权益英文到中文 fallback
