  'Headline slot': '头条露出位',
  'Contact Us': '联系我们',
};

function translateTierName(locale: Locale, name?: string) {
  if (!name) return name;
  if (locale !== 'zh') return name;
  return TIER_NAME_ZH[name] ?? name;
}

function translateBenefit(locale: Locale, benefit: string) {
  if (locale !== 'zh') return benefit;
  return BENEFIT_ZH[benefit] ?? benefit;
}

function translatePrice(locale: Locale, price?: string) {
  if (!price) return price;
  if (locale !== 'zh') return price;
  return BENEFIT_ZH[price] ?? price;
}

