    return {
      sponsorWallTitle: 'Featured Partners of 30 Years',
      footerTagline: 'Empowering professionals, entrepreneurs, and students since 1996.',
      explore: 'Explore',
      contact: 'Contact',
      links: {
        mission: 'Our Mission',
        journey: '30-Year Journey',
        sponsorship: 'Sponsorship',
        membership: 'Membership',
      },
      email: 'Email: contact@necina.org',
    };
  }, [locale]);

  return (
    <div
      className="min-h-screen transition-all duration-500 ease-in-out"
      style={{
        backgroundColor: 'var(--surface)',
        color: 'var(--text)',
        backgroundImage: 'var(--hero)',
      }}
    >
      <Navbar
        locale={locale}
        setLocale={setLocale}
        designStyle={designStyle}
        setDesignStyle={setDesignStyle}
      />

      <main key={`${locale}-${designStyle}`}>
        <Hero locale={locale} designStyle={designStyle} />
        <NoticeBanner locale={locale} designStyle={designStyle} />
        <MissionJourney locale={locale} designStyle={designStyle} />
        <ConversionBlock locale={locale} designStyle={designStyle} />
