                <button
                  key={type}
                  type="button"
                  onClick={() => setFormType(type)}
                  className={`flex-1 py-6 text-xs font-black uppercase tracking-[0.2em] transition-all ${
                    formType === type ? 'bg-primary text-white shadow-[0_0_30px_rgba(41,176,233,0.2)]' : 'text-white/40 hover:bg-white/5 hover:text-white'
                  }`}
                >
                  {t.tabs[type]}
                </button>
              ))}
