                    </svg>
                  </div>
                  <h3 className="text-3xl font-black mb-3">{t.successTitle}</h3>
                  <p className="text-white/40">{t.successBody}</p>
                </div>
              ) : (
                <form onSubmit={handleSubmit} className="space-y-8">
                  <div className="grid md:grid-cols-2 gap-8">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black uppercase tracking-widest text-white/30 ml-1">{t.fields.nameLabel}</label>
                      <input
                        type="text"
                        required
                        className="w-full px-6 py-4 bg-white/5 border border-white/10 rounded-2xl text-white focus:border-primary outline-none transition-all placeholder-white/20"
