              <ul className="space-y-3 mb-8 flex-1 text-sm text-slate-500">{tier.benefits.map((benefit, bIdx) => (<li key={bIdx} className="flex items-start gap-3"><CheckIcon /><span>{benefit}</span></li>))}</ul>
