interface NavbarProps {
  locale: Locale;
  setLocale: (l: Locale) => void;
  designStyle: DesignStyle;
  setDesignStyle: (s: DesignStyle) => void;
}

const Navbar: React.FC<NavbarProps> = ({ locale, setLocale, designStyle, setDesignStyle }) => {
  const [isOpen, setIsOpen] = useState(false);
  const styleOptions: DesignStyle[] = ['classic', 'modern', 'minimal', 'bold'];

  const isModern = designStyle === 'modern';
  const isMinimal = designStyle === 'minimal';
  const isBold = designStyle === 'bold';
  const isDark = designStyle === 'modern' || designStyle === 'bold' || designStyle === 'classic';

  // Base Nav Styles
  const navBaseClass = isMinimal 
    ? "bg-white border-b border-slate-100 shadow-none" 
    : isBold
      ? "bg-slate-950/90 backdrop-blur-2xl border-b border-white/20 shadow-[0_10px_40px_rgba(0,0,0,0.5)]"
      : isModern 
        ? "bg-slate-950/80 backdrop-blur-md border-b border-white/10 shadow-2xl" 
        : "glass-morphism border-b border-brand-light-2";

  const textColorClass = isMinimal 
    ? "text-slate-500 hover:text-slate-900 text-sm font-semibold tracking-tight" 
    : isBold
      ? "text-white/70 hover:text-primary transition-all uppercase text-[11px] font-black tracking-widest"
      : isDark 
        ? "text-white/80 hover:text-white" 
        : "text-slate-600 hover:text-primary";

  const brandTextClass = isMinimal
    ? "text-slate-900 tracking-tighter"
    : isBold
      ? "text-white tracking-tighter"
      : isDark
        ? "text-white"
        : "bg-clip-text text-transparent bg-gradient-to-r from-primary to-primary-dark";

  return (
    <nav className={`fixed w-full z-50 transition-all duration-300 ${navBaseClass}`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-16 lg:h-20 items-center">
          {/* Logo Section */}
          <div className="flex-shrink-0 flex items-center space-x-3">
            <div className={`w-8 h-8 lg:w-10 lg:h-10 rounded-lg flex items-center justify-center transition-all ${isMinimal ? 'bg-slate-900' : isBold ? 'bg-gradient-to-br from-primary to-indigo-600 shadow-[0_0_20px_rgba(41,176,233,0.5)]' : 'bg-primary'}`}>
              <span className="text-white font-bold text-lg lg:text-xl">N</span>
            </div>
            <span className={`text-xl lg:text-2xl font-black transition-all ${brandTextClass}`}>
