                <a
                  key={item.label}
                  href={item.href}
                  className={`transition-colors duration-200 whitespace-nowrap ${textColorClass}`}
                >
                  {item.label}
                </a>
              ))}
            </div>

            {/* Language Toggle */}
            <div className={`flex items-center p-1 rounded-full transition-all ${isMinimal ? 'bg-slate-50 border border-slate-100' : isBold ? 'bg-white/10 border border-white/20' : isDark ? 'bg-white/5 border border-white/10' : 'bg-slate-100 border border-slate-200 shadow-inner'}`}>
              {(['en', 'zh'] as Locale[]).map((l) => (
