                  onClick={() => setLocale(l)}
                  className={`px-3 py-1 rounded-full text-[10px] font-black tracking-widest transition-all ${
                    locale === l 
                      ? isMinimal
                        ? 'bg-white text-slate-900 border border-slate-200 shadow-sm'
