                          ? 'bg-primary text-white shadow-[0_0_15px_rgba(41,176,233,0.6)]'
                          : isModern 
                            ? 'bg-primary text-white shadow-[0_0_15px_rgba(41,176,233,0.3)]' 
                            : 'bg-white text-primary shadow-sm' 
