import React, { useMemo } from 'react';
import { ANNIVERSARY_AGENDA } from '../constants';
import type { Locale, DesignStyle } from '../types';

type Props = {
  locale: Locale;
  designStyle: DesignStyle;
};

// 兼容：title / title_zh / title.en|zh 等
function pickText(locale: Locale, obj: any, baseKey: string): string | undefined {
  if (!obj) return undefined;

  const nested = obj[baseKey];
  if (nested && typeof nested === 'object') {
    const v = locale === 'zh' ? nested.zh : nested.en;
    if (typeof v === 'string' && v.trim()) return v;
  }

  const suffixKey = `${baseKey}_${locale === 'zh' ? 'zh' : 'en'}`;
  if (typeof obj[suffixKey] === 'string' && obj[suffixKey].trim()) return obj[suffixKey];

  if (typeof obj[baseKey] === 'string' && obj[baseKey].trim()) return obj[baseKey];

  return undefined;
}

// 英文到中文 fallback
const AGENDA_TRANSLATIONS: Record<string, string> = {
  'Registration & Networking': '签到注册与交流',
  'Opening Remarks': '开场致辞',
  'Keynote Session': '主旨演讲',
  'Legacy Panel': '传承圆桌',
  'Anniversary Gala Dinner': '周年庆晚宴',
  'NECINA President & Distinguished Guests': 'NECINA 会长及特邀嘉宾',
  'Founding Members': '创始成员',
  'Early check-in and community coffee hour.': '提前签到与社区交流时间。',
  TBD: '待定',
};

function translateIfNeeded(locale: Locale, text?: string) {
  if (!text) return text;
  if (locale !== 'zh') return text;
  return AGENDA_TRANSLATIONS[text] ?? text;
}

type ViewItem = {
  time: string;
  title: string;
  speaker?: string;
  description?: string;
};

