  'Speaking opportunity': '发言机会',
  'Premium branding': '高级品牌露出',
  'Naming rights': '冠名权',
  '20 Gala tickets': '20 张晚宴门票',
  'Headline slot': '头条露出位',
  'Contact Us': '联系我们',
};

function translateTierName(locale: Locale, name?: string) {
  if (!name) return name;
  if (locale !== 'zh') return name;
  return TIER_NAME_ZH[name] ?? name;
}

function translateBenefit(locale: Locale, benefit: string) {
  if (locale !== 'zh') return benefit;
  return BENEFIT_ZH[benefit] ?? benefit;
}

function translatePrice(locale: Locale, price?: string) {
  if (!price) return price;
  if (locale !== 'zh') return price;
  return BENEFIT_ZH[price] ?? price;
}

type ViewTier = {
  name: string;
  price: string;
  benefits: string[];
  isFeatured?: boolean;
};

export default function SponsorshipTiers({ locale, designStyle }: Props) {
  const t = useMemo(() => {
    if (locale === 'zh') {
      return {
        heading: '赞助 30 周年',
        subheading: '通过企业合作支持我们的社区发展。',
        cta: '咨询合作',
        featuredTag: '重点推荐',
      };
    }
    return {
      heading: 'Sponsorship Opportunity',
      subheading: 'Partner with NECINA to shape the future of technology in New England.',
      cta: 'Inquire Now',
      featuredTag: 'RECOMMENDED',
    };
  }, [locale]);

  const tiers: ViewTier[] = useMemo(() => {
    return SPONSOR_TIERS.map((tier: any) => {
      const rawName = pickText(locale, tier, 'name') ?? tier.name ?? '';
      const rawPrice = pickText(locale, tier, 'price') ?? tier.price ?? '';
      const rawBenefits = pickArray(locale, tier, 'benefits') ?? tier.benefits ?? [];

      const name = translateTierName(locale, rawName) ?? '';
      const price = translatePrice(locale, rawPrice) ?? '';
      const benefits = rawBenefits.map((b: string) => translateBenefit(locale, b));

      return { name, price, benefits, isFeatured: !!tier.isFeatured };
    });
  }, [locale]);

  const CheckIcon = (props: { className?: string }) => (
    <svg
