                <div className="text-7xl font-black text-white italic mb-10">{featured.price}</div>
                <ul className="grid md:grid-cols-2 gap-8 mb-16 flex-1">
                  {featured.benefits.map((b, i) => (<li key={i} className="flex items-start gap-4"><CheckIcon className="w-6 h-6" /><span className="text-lg font-bold text-white/80">{b}</span></li>))}
                </ul>
                <a href="#forms" className="w-full py-6 bg-white text-slate-950 rounded-[2rem] font-black text-2xl uppercase tracking-tighter text-center">{t.cta}</a>
              </div>
