            <div className="lg:col-span-6 grid sm:grid-cols-2 gap-8">
              {others.map((tier, idx) => (
                <div key={idx} className="rounded-[2.5rem] border border-white/10 bg-white/5 p-8 flex flex-col">
                  <h3 className="text-xs font-black uppercase tracking-[0.4em] text-white/40 mb-1">{tier.name}</h3>
