import React, { useState } from 'react';
import { NAV_ITEMS } from '../constants';
import { Locale, DesignStyle } from '../types';

interface NavbarProps {
  locale: Locale;
  setLocale: (l: Locale) => void;
  designStyle: DesignStyle;
  setDesignStyle: (s: DesignStyle) => void;
}

const Navbar: React.FC<NavbarProps> = ({ locale, setLocale, designStyle, setDesignStyle }) => {
  const [isOpen, setIsOpen] = useState(false);
  const styleOptions: DesignStyle[] = ['classic', 'modern', 'minimal', 'bold'];

  const isModern = designStyle === 'modern';
  const isMinimal = designStyle === 'minimal';
  const isBold = designStyle === 'bold';
  const isDark = designStyle === 'modern' || designStyle === 'bold' || designStyle === 'classic';

  // Base Nav Styles
  const navBaseClass = isMinimal 
    ? "bg-white border-b border-slate-100 shadow-none" 
    : isBold
      ? "bg-slate-950/90 backdrop-blur-2xl border-b border-white/20 shadow-[0_10px_40px_rgba(0,0,0,0.5)]"
      : isModern 
        ? "bg-slate-950/80 backdrop-blur-md border-b border-white/10 shadow-2xl" 
        : "glass-morphism border-b border-brand-light-2";

  const textColorClass = isMinimal 
    ? "text-slate-500 hover:text-slate-900 text-sm font-semibold tracking-tight" 
    : isBold
      ? "text-white/70 hover:text-primary transition-all uppercase text-[11px] font-black tracking-widest"
      : isDark 
