  const tiers: ViewTier[] = useMemo(() => {
    return SPONSOR_TIERS.map((tier: any) => {
      const rawName = pickText(locale, tier, 'name') ?? tier.name ?? '';
      const rawPrice = pickText(locale, tier, 'price') ?? tier.price ?? '';
      const rawBenefits = pickArray(locale, tier, 'benefits') ?? tier.benefits ?? [];

      const name = translateTierName(locale, rawName) ?? '';
      const price = translatePrice(locale, rawPrice) ?? '';
