              <p className="text-sm mb-4">{t.email}</p>
            </div>
          </div>

          <div className="pt-8 border-t border-white/10 text-center text-xs text-slate-500">
            © {new Date().getFullYear()} NECINA. Registered 501(c)(3) nonprofit.
          </div>
        </div>
      </footer>

      <AIAssistant />
    </div>
  );
};

