import React, { useState } from 'react';
import { NAV_ITEMS } from '../constants';
import { Locale, DesignStyle } from '../types';

interface NavbarProps {
  locale: Locale;
  setLocale: (l: Locale) => void;
  designStyle: DesignStyle;
  setDesignStyle: (s: DesignStyle) => void;
}

const Navbar: React.FC<NavbarProps> = ({ locale, setLocale, designStyle, setDesignStyle }) => {
  const [isOpen, setIsOpen] = useState(false);
  const styleOptions: DesignStyle[] = ['classic', 'modern', 'minimal', 'bold'];

  const isModern = designStyle === 'modern';
  const isMinimal = designStyle === 'minimal';
  const isBold = designStyle === 'bold';
  const isDark = designStyle === 'modern' || designStyle === 'bold' || designStyle === 'classic';

  // Base Nav Styles
  const navBaseClass = isMinimal 
    ? "bg-white border-b border-slate-100 shadow-none" 
    : isBold
      ? "bg-slate-950/90 backdrop-blur-2xl border-b border-white/20 shadow-[0_10px_40px_rgba(0,0,0,0.5)]"
      : isModern 
        ? "bg-slate-950/80 backdrop-blur-md border-b border-white/10 shadow-2xl" 
        : "glass-morphism border-b border-brand-light-2";

  const textColorClass = isMinimal 
    ? "text-slate-500 hover:text-slate-900 text-sm font-semibold tracking-tight" 
    : isBold
      ? "text-white/70 hover:text-primary transition-all uppercase text-[11px] font-black tracking-widest"
      : isDark 
        ? "text-white/80 hover:text-white" 
        : "text-slate-600 hover:text-primary";

  const brandTextClass = isMinimal
    ? "text-slate-900 tracking-tighter"
    : isBold
      ? "text-white tracking-tighter"
      : isDark
        ? "text-white"
        : "bg-clip-text text-transparent bg-gradient-to-r from-primary to-primary-dark";

  const handleNavClick = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    // Prevent default anchor behavior which can cause routing issues in some environments
    e.preventDefault();

    // Extract ID from href
    const id = href.replace('#', '');
    const element = document.getElementById(id);

    if (element) {
      // Close mobile menu first
      setIsOpen(false);

      // Calculate scroll position with offset for fixed navbar
      const navbarHeight = 80;
      const elementPosition = element.getBoundingClientRect().top;
      const offsetPosition = elementPosition + window.pageYOffset - navbarHeight;

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth'
      });

      // Update URL hash without jumping
      window.history.pushState(null, '', href);
    } else {
      // Fallback for missing elements
      setIsOpen(false);
    }
  };

  return (
    <nav className={`fixed w-full z-50 transition-all duration-300 ${navBaseClass}`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-16 lg:h-20 items-center">
          {/* Logo Section */}
          <div className="flex-shrink-0 flex items-center space-x-3">
            <div className={`w-8 h-8 lg:w-10 lg:h-10 rounded-lg flex items-center justify-center transition-all ${isMinimal ? 'bg-slate-900' : isBold ? 'bg-gradient-to-br from-primary to-indigo-600 shadow-[0_0_20px_rgba(41,176,233,0.5)]' : 'bg-primary'}`}>
              <span className="text-white font-bold text-lg lg:text-xl">N</span>
            </div>
            <span 
              className={`text-xl lg:text-2xl font-black transition-all cursor-pointer ${brandTextClass}`}
              onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
            >
              NECINA
            </span>
          </div>

          {/* Desktop Navigation */}
          <div className="hidden lg:flex space-x-8 items-center">
            <div className={`flex space-x-6 mr-4 border-r pr-6 transition-all ${isDark ? 'border-white/10' : 'border-slate-100'}`}>
              {NAV_ITEMS.map((item) => (
                <a
                  key={item.label}
                  href={item.href}
                  onClick={(e) => handleNavClick(e, item.href)}
                  className={`transition-colors duration-200 whitespace-nowrap cursor-pointer ${textColorClass}`}
                >
                  {item.label}
                </a>
              ))}
            </div>

            {/* Language Toggle (Desktop) */}
            <div className={`flex items-center p-1 rounded-full transition-all ${isMinimal ? 'bg-slate-50 border border-slate-100' : isBold ? 'bg-white/10 border border-white/20' : isDark ? 'bg-white/5 border border-white/10' : 'bg-slate-100 border border-slate-200 shadow-inner'}`}>
              {(['en', 'zh'] as Locale[]).map((l) => (
                <button
                  key={l}
                  onClick={() => setLocale(l)}
                  className={`px-3 py-1 rounded-full text-[10px] font-black tracking-widest transition-all ${
                    locale === l 
                      ? isMinimal
                        ? 'bg-white text-slate-900 border border-slate-200 shadow-sm'
                        : isBold
                          ? 'bg-primary text-white shadow-[0_0_15px_rgba(41,176,233,0.6)]'
                          : isModern 
                            ? 'bg-primary text-white shadow-[0_0_15px_rgba(41,176,233,0.3)]' 
                            : 'bg-white text-primary shadow-sm' 
                      : isDark ? 'text-white/40 hover:text-white/60' : 'text-slate-500 hover:text-slate-700'
                  }`}
                >
                  {l.toUpperCase()}
                </button>
              ))}
            </div>

            {/* Style Tab Switcher */}
            <div className={`flex items-center p-1 rounded-full transition-all ${isMinimal ? 'bg-slate-50 border border-slate-100' : isBold ? 'bg-white/10 border border-white/20' : isDark ? 'bg-white/5 border border-white/10' : 'bg-slate-100 border border-slate-200'}`}>
              {styleOptions.map((style) => (
                <button
                  key={style}
                  onClick={() => setDesignStyle(style)}
                  className={`px-2.5 py-1 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${
                    designStyle === style
                      ? isMinimal
                        ? 'bg-slate-900 text-white shadow-md'
                        : isBold
                          ? 'bg-gradient-to-r from-primary to-indigo-600 text-white shadow-[0_0_20px_rgba(99,102,241,0.5)]'
                          : isModern
                            ? 'bg-primary text-white shadow-[0_0_15px_rgba(41,176,233,0.4)]'
                            : 'bg-white text-primary shadow-sm'
                      : isDark ? 'text-white/30 hover:text-white/50' : 'text-slate-500 hover:text-slate-700'
                  }`}
                >
                  {style}
                </button>
              ))}
            </div>

            <a 
              href="#sponsorship"
              onClick={(e) => handleNavClick(e, '#sponsorship')}
              className={`px-6 py-2 rounded-full font-bold text-xs transition-all active:scale-95 cursor-pointer ${
                isMinimal
                ? 'bg-primary text-white hover:bg-primary-hover shadow-none'
                : isBold
                ? 'bg-gradient-to-r from-primary to-indigo-600 text-white shadow-xl hover:shadow-primary/40 uppercase tracking-widest'
                : 'bg-primary text-white hover:bg-primary-hover ring-4 ring-primary/10'
              }`}
            >
              Support Us
            </a>
          </div>

          {/* Mobile Right Section */}
          <div className="lg:hidden flex items-center space-x-3">
            {/* Language Toggle (Always visible on mobile top bar) */}
            <div className={`flex items-center p-0.5 rounded-full transition-all ${isMinimal ? 'bg-slate-50 border border-slate-100' : isBold ? 'bg-white/10 border border-white/20' : isDark ? 'bg-white/5 border border-white/10' : 'bg-slate-100 border border-slate-200'}`}>
              {(['en', 'zh'] as Locale[]).map((l) => (
                <button
                  key={l}
                  onClick={() => setLocale(l)}
                  className={`px-2.5 py-1 rounded-full text-[9px] font-black tracking-widest transition-all ${
                    locale === l 
                      ? isMinimal
                        ? 'bg-white text-slate-900 border border-slate-200 shadow-sm'
                        : isBold
                          ? 'bg-primary text-white shadow-[0_0_10px_rgba(41,176,233,0.5)]'
                          : isModern 
                            ? 'bg-primary text-white shadow-[0_0_10px_rgba(41,176,233,0.3)]' 
                            : 'bg-white text-primary shadow-sm' 
                      : isDark ? 'text-white/40 hover:text-white/60' : 'text-slate-500 hover:text-slate-700'
                  }`}
                >
                  {l.toUpperCase()}
                </button>
              ))}
            </div>

            {/* Mobile Menu Button */}
            <button
              onClick={() => setIsOpen(!isOpen)}
              className={`p-2 transition-colors rounded-lg hover:bg-slate-500/10 ${isDark ? 'text-white/80' : 'text-slate-600'}`}
              aria-label="Toggle menu"
            >
              <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                {isOpen ? (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                ) : (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
                )}
              </svg>
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu Overlay */}
      {isOpen && (
        <div className={`lg:hidden absolute top-16 left-0 w-full animate-in slide-in-from-top duration-300 shadow-2xl ${
          isMinimal ? 'bg-white border-b border-slate-100' : isDark ? 'bg-slate-900/95 backdrop-blur-xl border-b border-white/10' : 'glass-morphism'
        }`}>
          <div className="px-6 pt-4 pb-8 space-y-6">
            <div className="space-y-2">
              {NAV_ITEMS.map((item) => (
                <a
                  key={item.label}
                  href={item.href}
                  className={`block px-4 py-4 text-xl font-black tracking-tight rounded-xl transition-all ${
                    isDark ? 'text-white hover:bg-white/5' : 'text-slate-800 hover:bg-slate-50'
                  }`}
                  onClick={(e) => handleNavClick(e, item.href)}
                >
                  {item.label}
                </a>
              ))}
            </div>

            <div className={`pt-6 border-t ${isDark ? 'border-white/10' : 'border-slate-100'}`}>
              {/* Style Theme Section in mobile menu */}
              <div className="flex items-center justify-between mb-6 px-4">
                <span className={`text-[10px] font-black uppercase tracking-[0.2em] ${isDark ? 'text-white/40' : 'text-slate-400'}`}>Style Theme</span>
                <div className="flex gap-2">
                  {styleOptions.map((s) => (
                    <button
                      key={s}
                      onClick={() => { setDesignStyle(s); setIsOpen(false); }}
                      className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest ${
                        designStyle === s 
                          ? 'bg-primary text-white' 
                          : isDark ? 'bg-white/5 text-white/40' : 'bg-slate-100 text-slate-500'
                      }`}
                    >
                      {s.charAt(0)}
                    </button>
                  ))}
                </div>
              </div>

              {/* Language Section in mobile menu (Secondary, consistent with top bar) */}
              <div className="flex items-center justify-between mb-8 px-4">
                <span className={`text-[10px] font-black uppercase tracking-[0.2em] ${isDark ? 'text-white/40' : 'text-slate-400'}`}>Language</span>
                <div className={`flex items-center p-0.5 rounded-full transition-all ${isMinimal ? 'bg-slate-50 border border-slate-100' : isBold ? 'bg-white/10 border border-white/20' : isDark ? 'bg-white/5 border border-white/10' : 'bg-slate-100 border border-slate-200'}`}>
                  {(['en', 'zh'] as Locale[]).map((l) => (
                    <button
                      key={l}
                      onClick={() => setLocale(l)}
                      className={`px-3 py-1 rounded-full text-[10px] font-black tracking-widest transition-all ${
                        locale === l 
                          ? isMinimal
                            ? 'bg-white text-slate-900 border border-slate-200 shadow-sm'
                            : isBold
                              ? 'bg-primary text-white shadow-[0_0_15px_rgba(41,176,233,0.6)]'
                              : isModern 
                                ? 'bg-primary text-white shadow-[0_0_15px_rgba(41,176,233,0.3)]' 
                                : 'bg-white text-primary shadow-sm' 
                          : isDark ? 'text-white/40 hover:text-white/60' : 'text-slate-500 hover:text-slate-700'
                      }`}
                    >
                      {l.toUpperCase()}
                    </button>
                  ))}
                </div>
              </div>

              <a 
                href="#sponsorship"
                onClick={(e) => handleNavClick(e, '#sponsorship')}
                className={`block w-full text-center py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-transform ${
                  isBold ? 'bg-gradient-to-r from-primary to-indigo-600 text-white' : isMinimal ? 'bg-slate-900 text-white' : 'bg-primary text-white'
                }`}
              >
                Become a Sponsor
              </a>
            </div>
          </div>
        </div>
      )}
    </nav>
  );
};

