// NECINA logo blue (used as CSS variables so the whole site can reference it)
const BRAND = {
  primary: '#29B0E9',
  primaryHover: '#218DBA',
  primaryDark: '#1B7297',
  bg1: '#EAF7FD',
  bg2: '#D4EFFB',
};

const App: React.FC = () => {
  const [locale, setLocale] = useState<Locale>(() => {
    const saved = localStorage.getItem('necina_locale');
    return saved === 'zh' || saved === 'en' ? saved : 'en';
  });

  const [designStyle, setDesignStyle] = useState<DesignStyle>(() => {
    const saved = localStorage.getItem('necina_style') as DesignStyle | null;
    return saved ?? 'modern';
  });

  // Apply style tokens to the document root to update CSS variables dynamically
  useEffect(() => {
    const tokens = STYLE_TOKENS?.[designStyle];
    if (tokens) {
      Object.entries(tokens).forEach(([property, value]) => {
        // Fix for Error: Argument of type 'unknown' is not assignable to parameter of type 'string'
        document.documentElement.style.setProperty(property, value as string);
      });
    }

    // Ensure brand variables always exist (even if tokens don't include them)
    document.documentElement.style.setProperty('--brand', BRAND.primary);
    document.documentElement.style.setProperty('--brandHover', BRAND.primaryHover);
    document.documentElement.style.setProperty('--brandDark', BRAND.primaryDark);
    document.documentElement.style.setProperty('--brandBg1', BRAND.bg1);
    document.documentElement.style.setProperty('--brandBg2', BRAND.bg2);

    document.documentElement.setAttribute('data-style', designStyle);
    localStorage.setItem('necina_style', designStyle);
  }, [designStyle]);

  // Persist locale + expose to DOM for future components
  useEffect(() => {
    document.documentElement.setAttribute('data-locale', locale);
    document.documentElement.lang = locale === 'zh' ? 'zh-CN' : 'en';
    localStorage.setItem('necina_locale', locale);
  }, [locale]);

  // Minimal i18n
  const t = useMemo(() => {
    if (locale === 'zh') {
      return {
        sponsorWallTitle: '30 年合作伙伴（示例）',
