      sponsorWallTitle: 'Featured Partners of 30 Years',
      footerTagline: 'Empowering professionals, entrepreneurs, and students since 1996.',
      explore: 'Explore',
      contact: 'Contact',
      links: {
        mission: 'Our Mission',
        sponsorship: 'Sponsorship',
        membership: 'Membership',
      },
      email: 'Email: contact@necina.org',
    };
  }, [locale]);

  return (
    <div
      className="min-h-screen transition-all duration-500 ease-in-out"
      style={{
        backgroundColor: 'var(--surface)',
        color: 'var(--text)',
        backgroundImage: 'var(--hero)',
      }}
    >
      <Navbar
        locale={locale}
        setLocale={setLocale}
        designStyle={designStyle}
        setDesignStyle={setDesignStyle}
      />

      <main key={`${locale}-${designStyle}`}>
        <Hero locale={locale} designStyle={designStyle} />
        <NoticeBanner locale={locale} designStyle={designStyle} />

        <div className="animate-reveal">
          <EventGallery locale={locale} designStyle={designStyle} />
        </div>

        <MissionJourney locale={locale} designStyle={designStyle} />

        <div className="animate-reveal">
          <VideoSection locale={locale} designStyle={designStyle} />
        </div>

        <ConversionBlock locale={locale} designStyle={designStyle} />
        <StayTuned locale={locale} designStyle={designStyle} />

        <div style={{ backgroundColor: 'var(--surface2)', borderTop: '1px solid var(--border)' }}>
          <ProgramAgenda locale={locale} designStyle={designStyle} />
        </div>

        <div id="sponsorship">
          <SponsorshipTiers locale={locale} designStyle={designStyle} />
        </div>

        <div id="forms">
          <InterestForms locale={locale} designStyle={designStyle} />
        </div>

        {/* Sponsor Wall */}
        <section className="py-16" id="sponsors" style={{ backgroundColor: 'var(--surface)' }}>
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <p
