            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-8 opacity-30 grayscale hover:grayscale-0 transition-all duration-700 items-center">
              {['Google', 'MIT', 'Microsoft', 'Pfizer', 'State Street', 'Liberty Mutual'].map((brand) => (
                <div key={brand} className="text-xl font-black text-center" style={{ color: 'var(--text)' }}>
                  {brand}
