        <div>
          <h3 className="text-2xl font-black text-center text-slate-400 uppercase tracking-[0.2em] mb-12">{t.journeyTitle}</h3>
          <div className="grid md:grid-cols-3 gap-8">
            {t.items.map((item, idx) => (
              <div 
                key={item.id} 
                className="group p-8 rounded-3xl bg-brand-light border border-brand-light-2 hover:shadow-2xl transition-all cursor-default" 
                onMouseEnter={() => setOpenId(item.id)} 
                onMouseLeave={() => setOpenId(null)}
              >
                <div className="w-12 h-12 bg-primary text-white rounded-xl flex items-center justify-center mb-6 font-bold text-xl">{idx + 1}</div>
                <h4 className="text-xl font-black text-slate-900 mb-4">{item.title}</h4>
                <div className={`overflow-hidden transition-all duration-500 ${openId === item.id ? 'max-h-40 opacity-100 mt-4' : 'max-h-0 opacity-0'}`}>
                  <p className="text-slate-600 leading-relaxed">{item.desc}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

export default MissionJourney;
